        const answer = down ? amount * unit.factor : amount / unit.factor;
        const wrongWay = down ? amount : amount * unit.factor;
        const additive = down ? amount + unit.factor : amount - unit.factor;
        const direction = down ? "smaller" : "larger";
        const operation = down ? "multiply" : "divide";
        const equation = `${amount} ${down ? "×" : "÷"} ${unit.factor} = ${answer}`;
        const wrongWayFeedback = down
          ? `${wrongWay} leaves the original unit count unchanged. A ${to} is smaller, so each ${from} becomes ${unit.factor} ${to}s.`
          : `${wrongWay} converts in the opposite direction. A ${to} is larger, so divide by ${unit.factor}.`;
