      const { total, justCounted, second: secondTrap, secondFeedback } = second(picks, counts);
      const phrase = picks
        .map((p, i) => `${counts[i]} ${counts[i] === 1 ? COINS[p].label : COINS[p].plural}`)
        .join(", ")
        .replace(/, ([^,]*)$/, picks.length > 2 ? ", and $1" : " and $1");
      const sum = picks.map((p, i) => `${COINS[p].cents * counts[i]}`).join(" + ");
      return {
        tag: "coin-total",
        answer: { counted: [], entry: total },
        widget: {
          type: "moneyBoard",
          mode: "count",
          prompt: `How many cents is ${phrase}?`,
          show: picks.map((p, i) => ({ cents: COINS[p].cents, label: COINS[p].label, count: counts[i] })),
          answerCents: total,
          commonEntries: [
            {
              cents: justCounted,
              feedback: `That counts the COINS, not what they are worth. There are ${count(justCounted, "coin")} on the board, but ${sum} = ${total} cents.`,
            },
            {
              cents: secondTrap,
              feedback: `${secondFeedback} Every coin counts, at its own value: ${sum} = ${total} cents.`,
            },
          ],
          fallbackFeedback: `Count each coin's VALUE, biggest first: ${sum} = ${total} cents.`,
          // Fires when the coins tapped along the way add to the right total but the typed entry does
          // not — the learner counted correctly and then mis-transcribed.
          mismatchFeedback: `Your counting was right — the coins do add to ${total} — but the number typed does not match it. Enter ${total}.`,
          showDollars: false,
          commonTotals: [],
          successFeedback: `${total}¢ — every coin's value counted.`,
        },
      };
