        const right = `0.${rightDigits.join("")}`;
        return mcq(
          rand,
          "place-compare",
          `In comparing ${left} and ${right}, which place decides the winner?`,
          [`The ${PLACE[at]} place`, `All places to the left tie, and the first difference appears in ${PLACE[at]}, so that place decides.`],
          [
            [`The ${PLACE[(at + 1) % 3]} place`, `${PLACE[(at + 1) % 3]} is not the first unequal column. The comparison is already decided in ${PLACE[at]}.`],
            [`The ${PLACE[(at + 2) % 3]} place`, `A later place cannot override an earlier difference. The first unequal digits are in ${PLACE[at]}.`],
            [`The ones place`, `Both numbers have 0 in the ones place, so that column ties. The first difference is in ${PLACE[at]}.`],
          ]
        );
