            // Both signs of the multiplier appear, as the authored parens lessons do: a positive-only
            // generator could not serve tse-parens-negative, which exists for the negative case.
            const a = pick(r, 0, 1) === 0 ? mag : -mag;
            const x = pick(r, R.x[0], R.x[1]);
            const c = pick(r, 0, 1) === 0 ? pick(r, 1, 9) : -pick(r, 1, 9);
