      const FOOD = [
        { item: "pie", piece: "piece" },
        { item: "pizza", piece: "slice" },
        { item: "cake", piece: "piece" },
      ] as const;
      const { n, sc, share } = draw(
        rand,
        (r) => ({ n: pick(r, 3, 10), sc: pick(r, 0, FOOD.length - 1), share: pick(r, 0, 1) === 1 }),
        () => true
      );
      const f = FOOD[sc];
      const prompt = share
