      const signed = (k: number) => (k < 0 ? `− ${-k}` : `+ ${k}`);
      // Spaced inside an equation, compact in prose: "y = |x| + 7" but "adding 7".
      const bare = (k: number) => (k < 0 ? `${-k} down` : `${k} up`);

