        const other = overY ? `y = −√x` : `y = √(−x)`;
        return mcq(
          rand,
          "reflect-fn",
          `Which rule reflects y = √x over the ${axis}?`,
          [
            correct,
            overY
              ? `Right — negating the INPUT mirrors the curve across to the left of the axis.`
              : `Right — the minus in FRONT negates every output, dropping the curve below the axis.`,
          ],
          [
            [
              other,
              overY
                ? `The minus in FRONT flips over the x-axis instead — the curve keeps its inputs and drops below.`
                : `Negating the INPUT flips over the y-axis instead — the curve mirrors sideways rather than dropping.`,
            ],
            [`y = −√(−x)`, `Two minuses flip over BOTH axes at once, which is a half-turn rather than a single mirror.`],
            [`y = √x`, `That is the original, with no minus anywhere — so nothing is reflected at all.`],
          ]
        );
