            wrong: [
              [[0, 3, 2], `${rows} + ${each} joins the row count to one row. Equal rows require multiplication, not one addition.`],
            ],
            missFeedback: `Use the two row numbers with ×. The poster can be read as ${rows} × ${each} or turned to ${each} × ${rows}.`,
            successFeedback: `Both directions count the same ${total} stars: ${rows} × ${each} = ${each} × ${rows}.`,
