  if(task==="evaluateAtX")return{requiredExplorations:2,requiredStageKeys:[`evaluate:${target}:substitute`,`evaluate:${target}:value`]};
  if(task==="compareStart")return{requiredExplorations:Math.min(lines.length+1,4),requiredStageKeys:[...lines.map(line=>`line:${line.id}:intercept`),"compare:starts"]};
  if(task==="compareRate")return{requiredExplorations:Math.min(lines.length+1,4),requiredStageKeys:[...lines.map(line=>`line:${line.id}:slope`),"compare:rates"]};
