  const numeric=legacy.widget.type==="numeric",choice=legacy.widget.type==="mcq",point=legacy.widget.type==="pointEntry";
  if(!numeric&&!choice&&!point)throw new Error(`affineRelationshipLab cannot wrap ${legacy.widget.type} for ${tag}@${form}`);
