export const VARIANT_GENERATORS: readonly VariantGen[] = GENERATORS;

/* ------------------------------------------------------------------ */
/* THE RESOLVER.
 *
 * Dispatch used to be an exact string match: a generator fired only where an authored step happened
 * to carry a conceptTag spelled identically to the generator's tag. It almost never did. Of the seven
 * generators above, five matched ZERO authored steps and two matched four apiece — 8 of 5,118 tagged
 * steps, 0.16%. Practice and review were serving authored items essentially always, and the whole
 * freshness mechanism was switched off by a naming mismatch rather than by any missing mathematics.
 *
 * The cause is structural, not clerical. The corpus carries 1,165 distinct conceptTags and 1,161 of
 * them appear in exactly one course: the namespace is course-local, roughly four steps per tag. So
 * tags are not a shared vocabulary that a generator can be written against — they are local labels,
 * and the same mathematics wears a different name in every course it appears in. `tse-solve-two-step`
 * and `eq-two-step` are the same skill; nothing in the data says so.
 *
 * This table says so. It maps an authored conceptTag onto the generator whose problems are a faithful
 * substitute for that tag's authored items.
 *
 * THE BAR FOR AN ENTRY, and it is deliberately high. A generated problem REPLACES the authored one,
 * so an alias is a claim that the swap costs the learner nothing:
 *
 *   SAME SKILL      the generator asks the question the tag's items ask — not an adjacent one.
 *   SAME FORM       the answer is the same KIND of quantity, reachable by the same procedure.
 *   SAME BAND       the surface is grade-appropriate for the lesson the tag lives in.
 *   TRAPS TRANSFER  the generator's misconceptions are the ones this tag's learners actually make.
 *
 * Every entry below was verified by reading the tag's authored steps. Fuzzy matching is not admissible
 * here and was tried and rejected: a name-similarity pass proposed `two-step` (a Grade-2 lesson about
 * "18 birds, then 24 more, then 15 fly off") for the two-step EQUATION generator, and pulled
 * `tc-cpctc` — congruent triangles — into the percent generator on the strength of the letters "pct".
 * Either alias would have put an algebra prompt in front of a seven-year-old. Entries are added by
 * hand, with the tag's items read, or they are not added.
 *
 * Rejections are recorded as loudly as acceptances, because the next person to look at this will
 * re-propose them.
 */
export interface AliasTarget {
  gen: string;
  form: VariantForm;
}

/** An alias is either a bare generator tag (default form) or a generator plus the form that tag needs. */
export type AliasSpec = string | AliasTarget;

export const CONCEPT_ALIASES: Readonly<Record<string, AliasSpec>> = {
  // — Two-step equations ————————————————————————————————————
  // Authored: "Solve: 5x + 3 = 28". The generator's form exactly.
  "tse-solve-two-step": "eq-two-step",
  // Same equation with a negative coefficient, and the generator's negative FORM carries one extra
  // trap the positive form cannot express: dividing by |a| and losing the sign. That is the
  // misconception this lesson exists for.
  "tse-solve-negative-coeff": { gen: "eq-two-step", form: "negative" },
  // a(x ± c) = d — a different procedure (distribute or divide first) and a different mistake set,
  // which is why "parens" is a form rather than a sign tweak. The generator draws BOTH signs of the
  // multiplier, which is what lets one form serve all three authored parens tags.
  "tse-parens-solve": { gen: "eq-two-step", form: "parens" },
  "tse-parens-negative": { gen: "eq-two-step", form: "parens" },
  "tse-parens-mixed": { gen: "eq-two-step", form: "parens" },

  // — Perimeter, area, and the choice between them ———————————
  // Grade 3-4. `area-perimeter-word-problems` genuinely contains both, so it takes the mixed form.
  "area-formula": { gen: "rect-measure", form: "area" },
  "area-perimeter-word-problems": { gen: "rect-measure", form: "mixed" },

  // — Angles that make a whole ———————————————————————————————
  "triangle-angle-sum": "angle-sum",
  "additive-angles": { gen: "angle-sum", form: "adjacent" },
  "missing-angle": { gen: "angle-sum", form: "missing" },

  // — Metric conversion ——————————————————————————————————————
  // `metric-badges` drills the single facts (1 kg = 1000 g) and `convert-length` /
  // `convert-mass-volume` apply them, but every practice item under all three is one conversion, so
  // one form serves them. `multistep-convert` climbs two rungs and gets its own.
  "metric-badges": "metric-convert",
  "convert-length": "metric-convert",
  "convert-mass-volume": "metric-convert",
  "multistep-convert": { gen: "metric-convert", form: "multistep" },

  // — Rounding ———————————————————————————————————————————————
  "round-any-place": "round-place",
  "round-to-whole": { gen: "round-place", form: "whole" },
  "round-any-decimal-place": { gen: "round-place", form: "decimalPlace" },

  // — Subtraction within 20: one fact, four strategies ————————
  // Each authored tag drills a different STRATEGY for the same arithmetic, and the parenthetical in
  // the prompt is that strategy. The forms carry it, so a count-back lesson keeps counting back.
  "take-away": "subtract-within-20",
  "count-back": { gen: "subtract-within-20", form: "countBack" },
  "difference": { gen: "subtract-within-20", form: "difference" },
  "sub-facts": { gen: "subtract-within-20", form: "factFamily" },

  // — Subtraction within 100: the place-value ladder ——————————
  "sub-tens": "subtract-within-100",
  "sub-ones": { gen: "subtract-within-100", form: "ones" },
  "tno-subtract-tens": { gen: "subtract-within-100", form: "minusTens" },
  "sub-2digit": { gen: "subtract-within-100", form: "twoDigit" },
  "unbundle-sub": { gen: "subtract-within-100", form: "regroup" },

  // — Probability as a fraction ——————————————————————————————
  // Four Grade 7 tags, all fractionEntry, each taking the form its lesson asks. `sp-mixed-prob`
  // genuinely mixes theoretical and experimental items, so it gets the mixed form rather than being
  // split or rejected.
  "sp-theoretical-prob": "probability-fraction",
  "sp-relative-freq": { gen: "probability-fraction", form: "relFreq" },
  "sp-mixed-prob": { gen: "probability-fraction", form: "mixed" },
  "sp-compound-prob": { gen: "probability-fraction", form: "compound" },

  // — Counting coins —————————————————————————————————————————
  "mmt-coin-total": "coin-total",
  // REJECTED: `mmt-coin-reverse`. Same engine, but its BUILD mode grades a tray of placed coins
  // rather than a typed total, so the answer is a different shape and the traps are totals-on-the-way
  // rather than final answers. It needs its own generator, not a form of this one.

  // — Comparing by place value ———————————————————————————————
  // Four tags, three of them Grade 1 and one Grade 2, every item a placeCompare. Each takes the form
  // that matches the decision its lesson drills, so a "compare the ones" set never rolls an item the
  // tens already settle.
  "tno-compare-tens": "place-compare",
  "tno-compare-ones": { gen: "place-compare", form: "ones" },
  "tno-compare-any": { gen: "place-compare", form: "any" },
  "pv1000-compare": { gen: "place-compare", form: "hundreds" },

  // — Counting on ————————————————————————————————————————————
  // Both tags are 100% numberLineHop, one within 10 and one through the teens.
  "kc-count-on": "count-on-line",
  "kc-count-to-20": { gen: "count-on-line", form: "teen" },

  // — Comparing lengths ——————————————————————————————————————
  // Two bars in Grade 1 (cubes, paperclips), three in Grade 2 (inches).
  "smg1-length-compare": "length-compare",
  "smg1-length-order": { gen: "length-compare", form: "three" },
  "mmt-length-order": { gen: "length-compare", form: "three" },
  // REJECTED: `ks-longer-shorter`. Single-engine like the rest, but one of its items asks what you
  // must DO first to compare fairly — line the ends up — which is a procedure question the engine can
  // render (mode: "align") but a generator cannot pose without inventing the staggered start the
  // authored item depends on. It waits for an align-mode generator.

  // — Telling the time ———————————————————————————————————————
  // Five tags, two courses, and every practice item under them is already a clockSet: the engine fit
  // is not a judgement call, it is what the authored content does. Each tag gets the FORM its lesson
  // teaches, so a Grade 1 half-past set never rolls a 3:35 the dial cannot express at its step size.
  "smg1-time-hour": { gen: "time-set-clock", form: "hour" },
  "smg1-time-half-past": { gen: "time-set-clock", form: "halfPast" },
  "smg1-time-mixed": { gen: "time-set-clock", form: "halfPast" },
  "mmt-time-5min": "time-set-clock",
  "mmt-time-mixed": "time-set-clock",
  // REJECTED: `ks-longer-shorter` and the other length tags are single-engine too, but one of them
  // asks what you must DO first to compare fairly ("line the ends up") — a procedure question the
  // lengthCompare engine renders but a generator cannot pose. Left for a length generator that draws
  // staggered starts, which the engine's planned v2 supports.

  // — Two linear equations in two unknowns ————————————————————
  // Both tags are "Solve the system … What is x?" over integer solutions; the generator states which
  // variable it wants, exactly as the authored items do.
  "substitute-isolated": "sys-two-linear",
  "isolate-then-substitute": "sys-two-linear",
  // REJECTED: `tse-solve-realworld` — three of its four items are bare "Solve: 5x + 2 = 32", but the
  // fourth wraps the equation in a submarine's dive, and that framing is the whole point of the
  // lesson. The bar is that EVERY item under the tag is the same form; three of four is not it.
  // `tse-combine-negative` uses buildExpression, not numeric.
  // REJECTED: `two-step`, `two-step-trade` (Grade 2 — two-step ARITHMETIC word problems, not
  // equations); `g7-angle-equations` (the modelling from a geometric figure IS the lesson, and a bare
  // equation deletes it); `solve-inequality` (direction/boundary is the skill); `equation-meaning`
  // (testing whether a value satisfies an equation, not solving one); `tse-solve-negative-coeff` (the
  // generator draws a ≥ 2, so it cannot produce the negative coefficient that tag exists to drill);
  // `exp-coeff-equation`, `rf-equations` (exponential and rational, different procedures entirely).

  // — Subtracting a negative ————————————————————————————————
  // All three are Grade-7 integer add/subtract sets built around "a − (−b)".
  "rno-subtract-change": "int-subtract-negative",
  "rno-subtract-opposite": "int-subtract-negative",
  "rno-mixed-ops": "int-subtract-negative",
  // Same skill over decimals — the generator's decimal FORM, not a second generator. All three
  // authored items are "a − (−b)" at one or two places (−4.1 − (−2.9), 0.75 − (−0.25), 3.25 − (−1.5)).
  "rno-decimal-subtract": { gen: "int-subtract-negative", form: "decimal" },
  // REJECTED: `rno-mixed-rational` (only two of its four items are subtract-a-negative, and both are
  // word problems whose FRAMING — an overdraft, a hiker walking back — is what the lesson teaches);
  // `negative-numbers` (opposites and representing below-zero); `compare-negatives` (ordering, and it
  // uses the rationalCompare widget); `cn-add-sub` (complex numbers).

  // — Percent of a number ————————————————————————————————————
  // Authored: "What is 30% of 40?", "A $80 jacket is 25% off — how many dollars is the discount?".
  "percent-of": "pct-of-number",
  // REJECTED: `percent-reason` (the REVERSE — "25% of a number is 9, find the whole"; the generator's
  // traps diagnose the forward error and would misdiagnose this one); `pr-add-percent` (total after
  // tax/tip — the answer is n + p% of n, a different quantity); `pr-percent-change`;
  // `percent-meaning` (fraction ↔ percent conversion); `exp-percent` (growth and decay factors).

  // — Slope from two points ——————————————————————————————————
  // All three ask "find the slope of the line through (x₁, y₁) and (x₂, y₂)" and grade a number.
  "slope-formula": "lf-slope-two-points",
  "slope-count": "lf-slope-two-points",
  // slope-sign is about the SIGN, and the generator's second trap is precisely the sign flip from
  // subtracting the points in inconsistent order — the misconception that tag is built on.
  "slope-sign": "lf-slope-two-points",
  // REJECTED: `fg-rate-of-change` (same arithmetic, but the Grade-8 lesson is teaching the
  // rate-of-change FRAMING — "as x goes from 3 to 5, y goes from 10 to 18" — and the generator's
  // coordinate-pair prompt would overwrite the representation being taught);
  // `slope-intercept-read`, `point-slope-read` (reading slope off a FORM, not computing it from
  // points); `de-slope-field` (differential equations).

  // — Calculus ———————————————————————————————————————————————
  // `dr-power-rule` and `dr-chain-rule` already match by name; no alias needed and none is safe.
  // REJECTED: `dr-second-derivative`, `dr-chain-nested` (second/third derivatives and product-with-
  // chain — the generator produces neither); `ca-first-derivative-test` and the rest of the
  // `ca-` family (sign analysis, not computation).
  //
  // `in-definite-power` (∫₀ᵇ kxⁿ dx) has NO safe alias and therefore still fires nowhere. The nearest
  // candidates all miss: `in-definite-integral` drills the PROPERTIES of the integral (additivity,
  // reversed limits) over an unspecified f; `in-antiderivative` and `in-ftc-unified` mix polynomial
  // sums and non-zero lower limits the generator cannot express; `in-usub` needs substitution. This
  // is a real remaining hole and is left visible rather than papered over with a loose alias — the
  // fix is to broaden the generator to sums and an arbitrary lower limit, not to widen the table.
};

/** The generator and form that serve an authored conceptTag, or null. Exact tag first, then aliases. */
export function resolveGeneratorTag(tag: string): AliasTarget | null {
  if (GENERATORS.some((g) => g.tag === tag)) return { gen: tag, form: "default" };
  const a = CONCEPT_ALIASES[tag];
  if (a === undefined) return null;
  return typeof a === "string" ? { gen: a, form: "default" } : a;
}

export function hasVariants(tag: string): boolean {
  return resolveGeneratorTag(tag) !== null;
}

/** Deterministic: the same (tag, seed) always yields the same problem, on any device, forever. */
export function variantFor(tag: string, seed: string, band: Band = "core"): Variant | null {
  const resolved = resolveGeneratorTag(tag);
  if (resolved === null) return null;
  const g = GENERATORS.find((x) => x.tag === resolved.gen)!;
  // The seed hashes the AUTHORED tag, not the resolved one. Two tags aliased to the same generator
  // are different skills wearing the same machinery, and they should not hand a learner the identical
  // problem on the same day. Tags that match a generator by name are unaffected — for them the
  // authored tag and the resolved tag are the same string, so every existing seed still yields the
  // problem it always did.
  // Band is part of the deterministic input: same tag+seed+band, same problem,
  // forever. (Same seed at a DIFFERENT band is a different problem — that is
  // the point of the ladder, not a determinism leak.)
  return g.gen(mulberry32(hashSeed(`${tag}:${seed}`)), band, resolved.form);
}

/** Build a variant from an explicit generator + form. The single path used by item-level
 * declarations AND by the form sweep in the gate, so what ships is what is tested.
 *
 * Seeded on the generator and form as well as the caller's seed, so two steps in one lesson that
 * share a tag but declare different forms never receive the same problem. */
export function variantForGenForm(
  gen: string,
  form: string,
  seed: string,
  band: Band = "core"
): Variant | null {
  const g = GENERATORS.find((x) => x.tag === gen);
  if (g === undefined) return null;
  return g.gen(mulberry32(hashSeed(`${gen}:${form}:${seed}`)), band, form as VariantForm);
}

/** SURFACE-PRESERVING SUBSTITUTION — the one place that decides whether a generated variant may
 * stand in for an authored item.
 *
 * `variantFor` knows a tag's generator; it does not know what the authored STEP looked like. Both
 * the practice screen and the review queue replace `item.widget` wholesale, so without this guard a
 * tag whose generator emits `numeric` will quietly turn every item under it into a text field —
 * including the manipulative ones. That is how a learner mid-way through a balance-scale or
 * undo-machine lesson gets handed a form to type into, and it is a silent regression: nothing throws,
 * nothing fails, the item is even correctly graded. It is simply a worse lesson.
 *
 * A tag is a SKILL, not a SURFACE. Until variants can be declared per step rather than per tag, the
 * honest rule is that freshness may change the numbers but never the manipulative. Where the types
 * disagree the authored item is served unchanged — no refresh is strictly better than a downgrade.
 *
 * WHAT THIS GUARD DOES NOT DO (F2, D-03). It checks the widget's TYPE and nothing else: the spec
 * itself is handed to the renderer unparsed, so a generated spec the schema FORBIDS still reaches a
 * learner — which is how bvScatterPlot's stretch band drew a 10×10 grid against `PlotPointSpec`'s
 * `max(8)` without anything noticing. Parsing here was measured and deliberately NOT taken: it is
 * value-preserving (verified over the full generated corpus) but `WidgetSpec` is a ~100-member
 * discriminated union whose parse costs about 2.3× the generator that produced the spec, and
 * `variants.resolver.test.ts`'s corpus walk makes ~71k calls to this function inside a single 5s
 * test — the gate goes red on cost alone. Per-serve validation needs to get cheap first (validate
 * once per gen×form×band rather than once per serve), which is a larger change than this guard.
 * Until then the schema cap is enforced where it is affordable and LOUD: `variants.test.ts` parses
 * every generator × form × band, so an out-of-schema spec fails CI instead of reaching a learner.
 */
export function variantForStep(
  step: { widget?: { type?: string }; conceptTag?: string; variant?: { gen: string; form?: string } },
  seed: string,
  band: Band = "core"
): Variant | null {
  const surface = step.widget?.type;
  if (surface === undefined) return null;

  // A step's own declaration wins over its tag's alias. This is the only way a manipulative item
  // living inside a numeric tag can be refreshed at all.
  if (step.variant !== undefined) {
    const v = variantForGenForm(
      step.variant.gen,
      step.variant.form ?? "default",
      `${step.conceptTag ?? ""}:${seed}`,
      band
    );
    if (v === null) return null;
    return v.widget.type === surface ? v : null;
  }

  if (step.conceptTag === undefined) return null;
  const v = variantFor(step.conceptTag, seed, band);
  if (v === null) return null;
  return v.widget.type === surface ? v : null;
}

/** Every generator, exercised once from a seed — used by the practice screen and by the gate. */
export function variantsForTags(tags: readonly string[], seed: string): Variant[] {
  const out: Variant[] = [];
  for (const t of tags) {
    const v = variantFor(t, seed);
    if (v) out.push(v);
  }
  return out;
}
